---

### ✅ **Algorithm Recap (Recursive Version):**

1. If the number is **less than 10**, check if it is **0 or 7** (i.e., divisible by 7).
2. If the number is **two digits or less**, check if it is divisible by 7 using **modulo**.
3. Otherwise:
   - Remove the **last digit**.
   - Double it.
   - Subtract it from the **remaining number**.
   - Recursively check the result.

---

### ✅ **C++ Implementation:**

```cpp
#include <iostream>
using namespace std;

// Recursive function to check if a number is divisible by 7
bool isDivisibleBy7(int n) {
    // Base case: if the number is less than 10
    if (n < 10) {
        return (n == 0 || n == 7);
    }

    // If the number is two digits or less, use modulo
    if (n < 100) {
        return (n % 7 == 0);
    }

    // Recursive case: apply the algorithm
    int lastDigit = n % 10;
    int remaining = n / 10;
    int subtracted = remaining - 2 * lastDigit;

    return isDivisibleBy7(subtracted);
}

int main() {
    int num;
    cout << "Enter a number: ";
    cin >> num;

    if (isDivisibleBy7(num)) {
        cout << num << " is divisible by 7." << endl;
    } else {
        cout << num << " is not divisible by 7." << endl;
    }

    return 0;
}
```

---

